  scroll-behavior: smooth;
}

body {
  margin: 0;
  background: #fffdfb;
  color: #281b22;
  font-family: "DM Sans", sans-serif;
}

button,
input {
  font-family: inherit;
}

button {
  cursor: pointer;
}

a {
  color: inherit;
  text-decoration: none;
}

.app {
  min-height: 100vh;
}

header {
  height: 80px;
  max-width: 1350px;
  margin: auto;
  padding: 0 5%;
  display: flex;
  align-items: center;
  justify-content: space-between;
}

.logo {
  display: flex;
  align-items: center;
  gap: 10px;
}

.logo > span {
  width: 38px;
  height: 38px;
  background: #77364c;
  color: white;
  border-radius: 50%;
  display: grid;
  place-items: center;
  font-family: "Playfair Display", serif;
  font-style: italic;
  font-size: 22px;
}

.logo > div {
  display: flex;
  flex-direction: column;
}

.logo strong {
  letter-spacing: 3px;
  font-size: 13px;
}

.logo small {
  color: #8d8187;
  font-size: 7px;
  letter-spacing: 1.5px;
}

nav {
  display: flex;
  gap: 30px;
}

nav a {
  font-size: 11px;
  font-weight: 600;
}

.cart {
  height: 40px;
  padding: 0 18px;
  border: 0;
  border-radius: 30px;
  background: #281b22;
  color: white;
  font-size: 10px;
}

/* HERO */

.hero {
  min-height: 620px;
  padding: 60px max(6%, calc((100vw - 1250px) / 2));
  display: grid;
  grid-template-columns: 1fr 1fr;
  align-items: center;
  gap: 65px;
  background:
    linear-gradient(
      120deg,
      #faf5f1,
      #fffdfb,
      #f1e0da
    );
}

.subtitle {
  color: #98465f;
  font-size: 9px;
  font-weight: 700;
  letter-spacing: 2px;
}

.hero h1,
.collection h2,
.about h2 {
  font-family: "Playfair Display", serif;
}

.hero h1 {
  font-size: clamp(50px,5vw,76px);
  line-height: 0.98;
  margin: 18px 0;
}

.hero h1 em,
.about h2 em {
  color: #a44561;
}

.hero p {
  max-width: 500px;
  color: #786c72;
  line-height: 1.8;
  font-size: 13px;
}

.discover {
  min-height: 50px;
  padding: 0 22px;
  margin-top: 20px;
  border-radius: 30px;
  background: #77364c;
  color: white;
  display: inline-flex;
  align-items: center;
  font-size: 10px;
  font-weight: 700;
}

.heroPhoto {
  height: 520px;
}

.heroPhoto img {
  width: 100%;
  height: 100%;
  object-fit: cover;

  /* IMAGE HERO PAS FLOUTÉE */
  filter: none;

  border-radius:
    220px
    220px
    15px
    15px;
}

/* COLLECTION */

.collection {
  max-width: 1300px;
  margin: auto;
  padding: 100px 25px;
}

.collectionTop {
  display: flex;
  justify-content: space-between;
  align-items: end;
}

.collection h2 {
  font-size: 50px;
  margin: 8px 0 3px;
}

.collectionTop p {
  color: #857980;
  font-size: 9px;
}

.search {
  width: 260px;
  height: 45px;
  border: 1px solid #e4dad5;
  border-radius: 30px;
  padding: 0 15px;
  display: flex;
  align-items: center;
  gap: 9px;
}

.search input {
  border: 0;
  outline: 0;
  width: 100%;
  background: transparent;
  font-size: 10px;
}

.categories {
  display: flex;
  gap: 8px;
  margin: 30px 0;
  overflow-x: auto;
}

.categories button {
  flex: 0 0 auto;
  border: 1px solid #e5dbd6;
  background: white;
  padding: 9px 15px;
  border-radius: 30px;
  font-size: 9px;
}

.categories .active {
  background: #281b22;
  color: white;
}

/* 4 PHOTOS PAR LIGNE */

.products {
  display: grid;
  grid-template-columns: repeat(4, 1fr);
  gap: 32px 15px;
}

.productImage {
  height: 390px;
  position: relative;
  overflow: hidden;
  border-radius: 12px;
  background: #eee3de;
}

.productImage > img {
  width: 100%;
  height: 100%;
  object-fit: cover;
  transition:
    transform .4s,
    filter .4s;
}

/* LES PRODUITS NORMAUX NE SONT PAS FLOUTÉS */

.productImage > img:not(.blurred) {
  filter: none;
}

/* UNIQUEMENT locked:true */

.productImage > img.blurred {
  filter: blur(17px);
  transform: scale(1.12);
}

.productImage:not(.isLocked):hover img {
  transform: scale(1.035);
}

.productImage.isLocked {
  cursor: pointer;
}

.categoryBadge {
  position: absolute;
  z-index: 5;
  top: 12px;
  left: 12px;
  padding: 7px 10px;
  background: white;
  border-radius: 30px;
  font-size: 7px;
  font-weight: 700;
}

.heart {
  position: absolute;
  z-index: 5;
  top: 12px;
  right: 12px;
  width: 36px;
  height: 36px;
  border: 0;
  border-radius: 50%;
  background: white;
  font-size: 18px;
}

.lock {
  width: 135px;
  height: 95px;
  position: absolute;
  z-index: 6;
  inset: 0;
  margin: auto;
  border-radius: 14px;
  background: rgba(255,255,255,.92);
  backdrop-filter: blur(12px);
  display: flex;
  flex-direction: column;
  justify-content: center;
  align-items: center;
  box-shadow:
    0 15px 35px
    rgba(20,10,15,.15);
}

.lock > span {
  font-size: 20px;
}

.lock strong {
  margin-top: 4px;
  font-size: 9px;
}

.lock small {
  color: #8b7e84;
  margin-top: 3px;
  font-size: 6px;
}

.addCart {
  position: absolute;
  z-index: 5;
  left: 10px;
  right: 10px;
  bottom: 10px;
  height: 39px;
  border: 0;
  border-radius: 30px;
  background: rgba(40,27,34,.93);
  color: white;
  font-size: 8px;
  font-weight: 700;
  opacity: 0;
  transform: translateY(7px);
  transition: .25s;
}

.productImage:hover .addCart {
  opacity: 1;
  transform: none;
}

.productInfo {
  padding: 12px 3px;
}

.productInfo > small {
  color: #8b7e84;
  font-size: 7px;
  text-transform: uppercase;
}

.productInfo h3 {
  margin: 3px 0 7px;
  font-family: "Playfair Display", serif;
  font-size: 18px;
}

.productInfo > strong {
  color: #77364c;
  font-size: 11px;
}

.sizes {
  display: flex;
  gap: 4px;
  margin-top: 10px;
}

.sizes span {
  width: 25px;
  height: 22px;
  border: 1px solid #e4dad5;
  border-radius: 5px;
  display: grid;
  place-items: center;
  font-size: 7px;
}

/* ABOUT */

.about {
  background: #f7f0eb;
  padding: 90px max(6%, calc((100vw - 1150px) / 2));
  display: grid;
  grid-template-columns: 1fr 1fr;
  gap: 70px;
  align-items: center;
}

.about > img {
  width: 100%;
  height: 530px;
  object-fit: cover;
  filter: none;
  border-radius:
    220px
    220px
    15px
    15px;
}

.about h2 {
  font-size: 55px;
  margin: 10px 0 20px;
}

.about p {
  color: #776b71;
  font-size: 12px;
  line-height: 1.8;
}

footer {
  background: #281b22;
  color: white;
  text-align: center;
  padding: 50px 20px;
}

footer strong {
  letter-spacing: 3px;
}

footer p {
  color: #a99fa4;
  font-size: 9px;
}

/* MODALE */

.modalOverlay {
  position: fixed;
  z-index: 9999;
  inset: 0;
  padding: 20px;
  background: rgba(25,15,20,.65);
  backdrop-filter: blur(7px);
  display: flex;
  justify-content: center;
  align-items: center;
}

.modal {
  width: min(420px,100%);
  background: white;
  border-radius: 20px;
  padding: 32px 28px 27px;
  position: relative;
  text-align: center;
  box-shadow:
    0 30px 90px
    rgba(0,0,0,.3);
}

.close {
  position: absolute;
  right: 13px;
  top: 13px;
  width: 35px;
  height: 35px;
  border: 0;
  border-radius: 50%;
  background: #f5eeee;
  font-size: 20px;
}

.modalLogo {
  margin: auto;
  width: 55px;
  height: 55px;
  border-radius: 50%;
  background: #77364c;
  color: white;
  display: grid;
  place-items: center;
  font-family: "Playfair Display", serif;
  font-style: italic;
  font-size: 27px;
}

.selected {
  margin: 20px 0;
  background: #f9f5f2;
  padding: 8px;
  border-radius: 10px;
  display: flex;
  align-items: center;
  gap: 10px;
  text-align: left;
}

.selected img {
  width: 48px;
  height: 57px;
  object-fit: cover;
  border-radius: 6px;
  filter: blur(5px);
}

.selected > div {
  display: flex;
  flex-direction: column;
}

.selected small {
  font-size: 6px;
  color: #94888e;
}

.selected strong {
  font-family: "Playfair Display", serif;
  margin-top: 3px;
}

.modal h2 {
  font-family: "Playfair Display", serif;
  font-size: 27px;
}

.modal > p {
  color: #7d7177;
  font-size: 10px;
  line-height: 1.6;
}

.facebook,
.google,
.email {
  width: 100%;
  height: 49px;
  border-radius: 9px;
  position: relative;
  font-size: 10px;
  font-weight: 700;
}

.facebook {
  border: 0;
  background: #1877f2;
  color: white;
}

.facebook b,
.google b {
  position: absolute;
  left: 18px;
  font-size: 19px;
}

.google {
  margin-top: 9px;
  border: 1px solid #ddd5d1;
  background: white;
}

.email {
  border: 1px solid #281b22;
  background: white;
}

.separator {
  margin: 18px 0;
  display: flex;
  align-items: center;
  gap: 10px;
}

.separator span {
  flex: 1;
  height: 1px;
  background: #e5dcd7;
}

.separator small {
  font-size: 7px;
  color: #978b90;
}

/* TABLETTE */

@media (max-width: 1000px) {
  .products {
    grid-template-columns: repeat(3,1fr);
  }
}

/* MOBILE */

@media (max-width: 800px) {
  nav {
    display: none;
  }

  .hero {
    grid-template-columns: 1fr;
  }

  .heroPhoto {
    height: 500px;
  }

  .about {
    grid-template-columns: 1fr;
  }

  .products {
    grid-template-columns: repeat(2,1fr);
  }
}

@media (max-width: 550px) {
  header {
    height: 68px;
    padding: 0 15px;
  }

  .cart {
    font-size: 0;
    width: 42px;
    padding: 0;
  }

  .cart::before {
    content: "🛍️";
    font-size: 15px;
  }

  .hero {
    padding: 50px 18px;
  }

  .hero h1 {
    font-size: 47px;
  }

  .heroPhoto {
    height: 430px;
  }

  .collection {
    padding: 75px 12px;
  }

  .collectionTop {
    flex-direction: column;
    align-items: stretch;
    gap: 20px;
  }

  .collection h2 {
    font-size: 38px;
  }

  .search {
    width: 100%;
  }

  .products {
    grid-template-columns: repeat(2,1fr);
    gap: 25px 8px;
  }

  .productImage {
    height: 270px;
  }

  .lock {
    width: 110px;
    height: 82px;
  }

  .lock strong {
    font-size: 8px;
  }

  .productInfo h3 {
    font-size: 15px;
  }

  .sizes {
    display: none;
  }

  .addCart {
    opacity: 1;
    transform: none;
    height: 35px;
  }

  .about {
    padding: 70px 20px;
  }

  .about > img {
    height: 420px;
  }

  .about h2 {
    font-size: 45px;
  }
}
