import React, { useMemo, useState } from "react";

const products = [
  {
    id: 1,
    name: "Robe Soa",
    category: "Nouveautés",
    price: 129000,
    locked: false,
    image:
      "https://images.unsplash.com/photo-1515372039744-b8f02a3ae446?auto=format&fit=crop&w=900&q=85",
  },
  {
    id: 2,
    name: "Robe Mialy",
    category: "Soirée",
    price: 159000,
    locked: true,
    image:
      "https://images.unsplash.com/photo-1496747611176-843222e1e57c?auto=format&fit=crop&w=900&q=85",
  },
  {
    id: 3,
    name: "Robe Vola",
    category: "Décontractée",
    price: 99000,
    locked: false,
    image:
      "https://images.unsplash.com/photo-1490481651871-ab68de25d43d?auto=format&fit=crop&w=900&q=85",
  },
  {
    id: 4,
    name: "Robe Fara",
    category: "Cérémonie",
    price: 139000,
    locked: false,
    image:
      "https://images.unsplash.com/photo-1529139574466-a303027c1d8b?auto=format&fit=crop&w=900&q=85",
  },
  {
    id: 5,
    name: "Robe Kanto",
    category: "Décontractée",
    price: 119000,
    locked: true,
    image:
      "https://images.unsplash.com/photo-1539109136881-3be0616acf4b?auto=format&fit=crop&w=900&q=85",
  },
  {
    id: 6,
    name: "Robe Tahina",
    category: "Soirée",
    price: 179000,
    locked: false,
    image:
      "https://images.unsplash.com/photo-1502716119720-b23a1e3ae1b5?auto=format&fit=crop&w=900&q=85",
  },
  {
    id: 7,
    name: "Robe Sarobidy",
    category: "Cérémonie",
    price: 149000,
    locked: false,
    image:
      "https://images.unsplash.com/photo-1525507119028-ed4c629a60a3?auto=format&fit=crop&w=900&q=85",
  },
  {
    id: 8,
    name: "Robe Noro",
    category: "Nouveautés",
    price: 109000,
    locked: true,
    image:
      "https://images.unsplash.com/photo-1485230895905-ec40ba36b9bc?auto=format&fit=crop&w=900&q=85",
  },
  {
    id: 9,
    name: "Robe Lova",
    category: "Soirée",
    price: 169000,
    locked: false,
    image:
      "https://images.unsplash.com/photo-1496217590455-aa63a8350eea?auto=format&fit=crop&w=900&q=85",
  },
  {
    id: 10,
    name: "Robe Hasina",
    category: "Décontractée",
    price: 89000,
    locked: false,
    image:
      "https://images.unsplash.com/photo-1485968579580-b6d095142e6e?auto=format&fit=crop&w=900&q=85",
  },
  {
    id: 11,
    name: "Robe Aina",
    category: "Cérémonie",
    price: 155000,
    locked: true,
    image:
      "https://images.unsplash.com/photo-1521572163474-6864f9cf17ab?auto=format&fit=crop&w=900&q=85",
  },
  {
    id: 12,
    name: "Robe Tiana",
    category: "Nouveautés",
    price: 135000,
    locked: false,
    image:
      "https://images.unsplash.com/photo-1496747611176-843222e1e57c?auto=format&fit=crop&w=900&q=85",
  },
];

const categories = [
  "Toutes",
  "Nouveautés",
  "Soirée",
  "Cérémonie",
  "Décontractée",
];

const formatPrice = (price) =>
  new Intl.NumberFormat("fr-FR").format(price) + " Ar";

export default function App() {
  const [category, setCategory] = useState("Toutes");
  const [search, setSearch] = useState("");

  const [loginOpen, setLoginOpen] = useState(false);
  const [selectedProduct, setSelectedProduct] = useState(null);

  const filteredProducts = useMemo(() => {
    return products.filter((product) => {
      const categoryMatch =
        category === "Toutes" ||
        product.category === category;

      const searchMatch = product.name
        .toLowerCase()
        .includes(search.toLowerCase());

      return categoryMatch && searchMatch;
    });
  }, [category, search]);

  const openLockedProduct = (product) => {
    if (!product.locked) {
      return;
    }

    setSelectedProduct(product);
    setLoginOpen(true);
  };

  return (
    <>
      <style>{css}</style>

      <div className="app">
        <header>
          <a className="logo" href="#">
            <span>R</span>

            <div>
              <strong>RAVAKA</strong>
              <small>FEMME • MADAGASCAR</small>
            </div>
          </a>

          <nav>
            <a href="#collection">Nouveautés</a>
            <a href="#collection">Robes</a>
            <a href="#about">Notre univers</a>
          </nav>

          <button className="cart">
            🛍️ Panier
          </button>
        </header>

        {/* HERO NORMAL */}

        <section className="hero">
          <div>
            <small className="subtitle">
              ✦ COLLECTION FEMME
            </small>

            <h1>
              Trouvez la robe
              <br />
              qui vous fait
              <em> rayonner.</em>
            </h1>

            <p>
              Une sélection de robes modernes et élégantes
              disponible à Madagascar.
            </p>

            <a href="#collection" className="discover">
              Découvrir la collection →
            </a>
          </div>

          <div className="heroPhoto">
            <img
              src="https://images.unsplash.com/photo-1496747611176-843222e1e57c?auto=format&fit=crop&w=1100&q=90"
              alt="Collection Ravaka"
            />
          </div>
        </section>

        {/* COLLECTION */}

        <section className="collection" id="collection">
          <div className="collectionTop">
            <div>
              <small className="subtitle">
                SÉLECTION RAVAKA
              </small>

              <h2>
                Nos robes
              </h2>

              <p>
                {filteredProducts.length} modèles disponibles
              </p>
            </div>

            <div className="search">
              🔎

              <input
                type="search"
                placeholder="Rechercher..."
                value={search}
                onChange={(e) =>
                  setSearch(e.target.value)
                }
              />
            </div>
          </div>

          <div className="categories">
            {categories.map((item) => (
              <button
                key={item}
                className={
                  category === item ? "active" : ""
                }
                onClick={() =>
                  setCategory(item)
                }
              >
                {item}
              </button>
            ))}
          </div>

          <div className="products">
            {filteredProducts.map((product) => (
              <article
                className="product"
                key={product.id}
              >
                <div
                  className={`productImage ${
                    product.locked
                      ? "isLocked"
                      : ""
                  }`}
                  onClick={() =>
                    openLockedProduct(product)
                  }
                >
                  <img
                    src={product.image}
                    alt={product.name}
                    className={
                      product.locked
                        ? "blurred"
                        : ""
                    }
                  />

                  <span className="categoryBadge">
                    {product.category}
                  </span>

                  <button className="heart">
                    ♡
                  </button>

                  {/* UNIQUEMENT POUR LES PHOTOS FLOUTÉES */}

                  {product.locked && (
                    <div className="lock">
                      <span>🔒</span>

                      <strong>
                        Photo privée
                      </strong>

                      <small>
                        Cliquez pour voir
                      </small>
                    </div>
                  )}

                  {/* LES PHOTOS NORMALES ONT LE BOUTON PANIER */}

                  {!product.locked && (
                    <button
                      className="addCart"
                      onClick={(e) => {
                        e.stopPropagation();

                        alert(
                          `${product.name} ajouté au panier`
                        );
                      }}
                    >
                      Ajouter au panier
                    </button>
                  )}
                </div>

                <div className="productInfo">
                  <small>
                    {product.category}
                  </small>

                  <h3>
                    {product.name}
                  </h3>

                  <strong>
                    {formatPrice(product.price)}
                  </strong>

                  <div className="sizes">
                    <span>S</span>
                    <span>M</span>
                    <span>L</span>
                    <span>XL</span>
                  </div>
                </div>
              </article>
            ))}
          </div>
        </section>

        {/* ABOUT */}

        <section className="about" id="about">
          <img
            src="https://images.unsplash.com/photo-1483985988355-763728e1935b?auto=format&fit=crop&w=1100&q=85"
            alt="Boutique Ravaka"
          />

          <div>
            <small className="subtitle">
              NOTRE UNIVERS
            </small>

            <h2>
              Élégante.
              <br />
              Moderne.
              <br />
              <em>Malagasy.</em>
            </h2>

            <p>
              Découvrez des robes sélectionnées pour les
              femmes de Madagascar avec une expérience
              simple, moderne et adaptée au mobile.
            </p>
          </div>
        </section>

        <footer>
          <strong>
            RAVAKA
          </strong>

          <p>
            Mode femme • Madagascar 🇲🇬
          </p>
        </footer>

        {/* MODALE UNIQUEMENT POUR PRODUIT FLOUTÉ */}

        {loginOpen && (
          <div
            className="modalOverlay"
            onClick={() => setLoginOpen(false)}
          >
            <div
              className="modal"
              onClick={(e) =>
                e.stopPropagation()
              }
            >
              <button
                className="close"
                onClick={() =>
                  setLoginOpen(false)
                }
              >
                ×
              </button>

              <div className="modalLogo">
                R
              </div>

              {selectedProduct && (
                <div className="selected">
                  <img
                    src={selectedProduct.image}
                    alt=""
                  />

